import { Idioma } from "../../lib/i18n";

// Base de conocimiento del Asistente: temas de finanzas, negocio y
// economía que se responden con explicaciones propias, sin depender de
// ninguna API de IA. Es lo que le permite contestar "¿qué es el margen?"
// o "¿cómo pongo precio a un producto?" además de las preguntas sobre
// los datos del propio negocio (esas viven en acciones.ts).
//
// Por qué vive aquí y no en lib/i18n.ts: son textos largos que
// duplicarían el tamaño de ese archivo, y sobre todo, al tiparlos como
// Record<Idioma, string> TypeScript obliga a que cada tema traiga los 7
// idiomas — si falta uno, el build falla. En i18n.ts eso solo se
// detecta revisando a mano.
//
// Para agregar un tema nuevo basta con añadir una entrada más a este
// arreglo: el motor de detección (deteccion.ts) lo toma automáticamente.
export interface TemaConocimiento {
  id: string;
  // Escritas SIN acentos y en minúsculas: el texto de la persona se
  // normaliza igual antes de comparar, así "¿qué es el márgen?" y "que
  // es el margen" coinciden con la misma lista.
  palabras: string[];
  respuesta: Record<Idioma, string>;
}

